const body = $input.first().json.body || $input.first().json || {};
const events = body.events || [];
const ev = events[0] || {};
const source = ev.source || {};
const groupId = source.groupId || body.line_group_id || '';
const userId = source.userId || '';
const replyToken = ev.replyToken || '';
const text = (ev.message && ev.message.text) ? ev.message.text.trim() : (body.message || '');

const LINE_CHANNEL_ID = '2012318539';
const LINE_CHANNEL_SECRET = '2e841449fe0466ebba1abcf68953966b';
const LINE_ACCESS_TOKEN = 'Ay+Y4vexjlwSL2rRsoXfQg2CUzVp+/+wlH6QW1bXnpkNYsGESxmFiASTSaGix0xZPFgzIIEY/viNkxoM9Q+ErOW4ek7uwlX1WXQ6+kzXDKGRylI7CfiPS9dZQMBfe+CYMGosechkO1qhs0GpQna8aAdB04t89/1O/w1cDnyilFU=';

let coordinatorAction = 'sync_only';
let replyText = '';

if (ev.type === 'join' && groupId) {
  coordinatorAction = 'group_greeting';
  replyText = `สวัสดีค่ะ 🙏✨ บอทแอดมินประสานงาน Tori Marketing (AIFY @599fgktd) รายงานตัวเข้ากลุ่มเรียบร้อยแล้วนะคะ\n📌 รหัสกลุ่มประสานงาน: ${groupId}\nพร้อมดูแลแจ้งเตือนสถานะงาน รีพอร์ตโฆษณา และประสานงานทีมให้ตลอด 24 ชม. ค่ะ 😊`;
} else if (/^(เช็กรหัสกลุ่ม|รหัสกลุ่ม|#groupid)/i.test(text)) {
  coordinatorAction = 'group_id_check';
  replyText = `📌 รหัสกลุ่ม LINE สำหรับเชื่อมระบบ Tori Marketing คือ:\n${groupId || 'แชทส่วนตัว (' + userId + ')'} ค่ะ`;
} else if (/^(สรุปงาน|เช็กสถานะ|#status)/i.test(text)) {
  coordinatorAction = 'status_summary';
  replyText = `📊 [สรุปสถานะระบบประสานงาน Tori Marketing]\n• บอทประสานงาน: AIFY (@599fgktd) ออนไลน์ 100% ค่ะ\n• ระบบหลังบ้าน BaanTori & n8n: พร้อมรับคำสั่งค่ะ\nหากต้องการฝากงานด่วน พิมพ์ #งานด่วน ตามด้วยรายละเอียดได้เลยนะคะ 😊🙏`;
} else if (/^#งานด่วน/i.test(text)) {
  coordinatorAction = 'urgent_task';
  replyText = `🚨 รับทราบภารกิจด่วนฝั่ง Tori Marketing เรียบร้อยแล้วค่ะ ระบบได้บันทึกงานและแจ้งเตือนทีมแอดมินประสานงานให้ทันทีนะคะ 🙏✨`;
}

return [{
  json: {
    raw_body: body,
    coordinator_action: coordinatorAction,
    should_reply: Boolean(replyToken && replyText),
    group_id: groupId,
    user_id: userId,
    reply_token: replyToken,
    incoming_text: text,
    reply_text: replyText,
    line_channel_id: LINE_CHANNEL_ID,
    line_channel_secret: LINE_CHANNEL_SECRET,
    line_access_token: LINE_ACCESS_TOKEN
  }
}];
